create extension if not exists pgcrypto;
create type public.quiz_status as enum ('draft','published','closed');
create type public.question_kind as enum ('multiple_choice','true_false','short_text','fill_blank','oral','ordering');
create type public.review_kind as enum ('auto','pending','reviewed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',created_at timestamptz not null default now());
create table public.quizzes(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 1 and 160),description text,subject text,access_code text unique,status public.quiz_status not null default 'draft',time_limit integer check(time_limit is null or time_limit between 1 and 600),settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),published_at timestamptz,closed_at timestamptz);
create table public.questions(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,question_text text not null check(length(question_text) between 1 and 5000),question_type public.question_kind not null,points numeric(7,2) not null default 1 check(points between 0 and 1000),teacher_audio_path text,image_path text,explanation text,position integer not null default 0,created_at timestamptz not null default now(),unique(quiz_id,position));
create table public.answers(id uuid primary key default gen_random_uuid(),question_id uuid not null references public.questions(id) on delete cascade,answer_text text not null check(length(answer_text) between 1 and 1000),is_correct boolean not null default false,position integer not null default 0,unique(question_id,position));
create table public.quiz_sessions(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,participant_id uuid not null references auth.users(id) on delete cascade,student_name text not null check(length(student_name) between 1 and 80),status text not null default 'in_progress' check(status in ('in_progress','submitted')),joined_at timestamptz not null default now(),submitted_at timestamptz,unique(quiz_id,participant_id));
create table public.submissions(id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,session_id uuid not null unique references public.quiz_sessions(id) on delete cascade,total_score numeric(8,2) not null default 0,maximum_score numeric(8,2) not null default 0,grading_status text not null default 'pending' check(grading_status in ('pending','partial','complete')),submitted_at timestamptz not null default now());
create table public.student_answers(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions(id) on delete cascade,question_id uuid not null references public.questions(id) on delete cascade,answer_text text,selected_answer_ids uuid[] not null default '{}',audio_path text,awarded_points numeric(7,2),teacher_feedback text,review_status public.review_kind not null default 'pending',unique(submission_id,question_id));
create index quizzes_teacher_idx on public.quizzes(teacher_id,created_at desc);create index questions_quiz_idx on public.questions(quiz_id,position);create index answers_question_idx on public.answers(question_id);create index sessions_quiz_idx on public.quiz_sessions(quiz_id,joined_at desc);create index submissions_quiz_idx on public.submissions(quiz_id,submitted_at desc);create index student_answers_submission_idx on public.student_answers(submission_id);
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
